/**
 * Fails when `src/ipc/bindings.generated.ts` no longer matches the Rust command
 * surface.
 *
 * The file is generated by `src-tauri/tests/export_bindings.rs` and committed, so
 * the frontend build never needs a Rust toolchain. That only holds while the
 * committed copy stays in sync, which is what this checks: regenerate, then look
 * for a diff.
 *
 * Note this catches Rust changes that were not regenerated, not hand-edits to the
 * generated file: regenerating overwrites those before the diff is taken, so a
 * manual edit is silently reverted rather than reported. That is the safe
 * direction to fail in — the committed file always ends up matching Rust.
 *
 * Follows the precedent set by `check-query-keys.mjs` and `check-contrast.mjs`.
 */
import { execFileSync } from "node:child_process";

const GENERATED = "src/ipc/bindings.generated.ts";

function run(command, args) {
  return execFileSync(command, args, { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
}

try {
  run("cargo", ["test", "--manifest-path", "src-tauri/Cargo.toml", "--test", "export_bindings"]);
} catch (error) {
  console.error("Failed to regenerate the bindings.\n");
  console.error(error.stdout ?? "");
  console.error(error.stderr ?? "");
  process.exit(1);
}

let diff = "";
try {
  diff = run("git", ["diff", "--", GENERATED]);
} catch (error) {
  console.error(`Could not diff ${GENERATED}: ${error.message}`);
  process.exit(1);
}

if (diff.trim() !== "") {
  console.error(`${GENERATED} is out of date with the Rust commands.\n`);
  console.error(diff);
  console.error("Run: cargo test --manifest-path src-tauri/Cargo.toml --test export_bindings");
  console.error("then commit the regenerated file.");
  process.exit(1);
}

console.log(`${GENERATED} is in sync with the Rust commands.`);
